#generated by Gemini

import argparse
import pandas as pd


def find_best_mast_by_id(
    region_id,
    freq_GHz=2.580,
    landing_site_only=False,
    restrict_to_region=True,
    candidates_csv="candidates_coverage.csv",
    index_csv="site_tiles_index.csv",
):
  # Load datasets
  df_cand = pd.read_csv(candidates_csv)
  df_index = pd.read_csv(index_csv)

  # 1. Search for the region by ID
  match = df_index[df_index["id"] == region_id]

  if match.empty:
    print(f"Error: No region with ID {region_id} found in index.")
    print("Available region IDs and names:")
    for _, row in df_index.iterrows():
      print(f"  - ID {row['id']}: {row['name']}")
    return None

  region_info = match.iloc[0]
  region_name = region_info["name"]
  print(
      f"Selected Region: ID {region_id} - {region_name} (Lat:"
      f" {region_info['min_lat']}° to {region_info['max_lat']}°, Lon:"
      f" {region_info['min_lon']}° to {region_info['max_lon']}°)"
  )

  # 2. Optionally filter candidates by bounding box of the region
  if restrict_to_region:
    df_cand = df_cand[
        (df_cand["lat"] >= region_info["min_lat"])
        & (df_cand["lat"] <= region_info["max_lat"])
        & (df_cand["lon_e"] >= region_info["min_lon"])
        & (df_cand["lon_e"] <= region_info["max_lon"])
    ]
    print(f"Filtered to {len(df_cand)} candidate masts within this region.")
    if df_cand.empty:
      print("No candidate masts found inside this specific bounding box.")
      return None

  # 3. Apply landing site class restriction if requested
  if landing_site_only:
    df_cand = df_cand[df_cand["cls"].str.lower() == "landing_site"]
    print(f"Filtered to {len(df_cand)} masts with 'landing_site' class.")
    if df_cand.empty:
      print("No candidate masts matching 'landing_site' class found here.")
      return None

  # 4. Determine coverage metric column
  coverage_col = f"area_km2_{freq_GHz:.3f}GHz"
  if coverage_col not in df_cand.columns:
    raise ValueError(
        f"Coverage metric column '{coverage_col}' not found in candidates CSV."
    )

  # 5. Find the mast with the maximum coverage
  best_mast = df_cand.loc[df_cand[coverage_col].idxmax()]

  print("\n--- Best Mast Result ---")
  print(
      f"Mast ID: {best_mast['cand_id']} | Class: {best_mast['cls']} | Tile:"
      f" {best_mast['tile']}"
  )
  print(
      f"Coordinates: Lat {best_mast['lat']:.4f}°, Lon"
      f" {best_mast['lon_e']:.4f}° | Height: {best_mast['mast_height_m']}m"
  )
  print(
      f"Coverage ({coverage_col}): {best_mast[coverage_col]:.3f} km²"
  )

  return best_mast


if __name__ == "__main__":
  parser = argparse.ArgumentParser(
      description=(
          "Find the best mast site coverage for a given lunar region ID."
      )
  )

  parser.add_argument(
      "--region_id",
      type=int,
      required=True,
      help="Numerical ID of the target site region (e.g., 1 to 22)",
  )
  parser.add_argument(
      "--freq",
      type=float,
      default=1.800,
      help="Communication frequency in GHz (default: 1.800)",
  )
  parser.add_argument(
      "--landing_site_only",
      action="store_true",
      help="Restrict candidates to 'landing_site' class only",
  )
  parser.add_argument(
      "--no_restrict_region",
      action="store_true",
      help=(
          "Search globally across all regions instead of restricting to the"
          " selected region's bounding box"
      ),
  )

  args = parser.parse_args()

  find_best_mast_by_id(
      region_id=args.region_id,
      freq_GHz=args.freq,
      landing_site_only=args.landing_site_only,
      restrict_to_region=not args.no_restrict_region,
  )

  #example script run:
  #python optimal_gNB.py --region_id 15 --freq 2.580 --landing_site_only